// ============================================================
// Metric descriptions + data-source bindings
//
// Generated by 10 parallel agents from page-rendered metrics in
// app/(dashboard)/metrics/page.tsx. Each description explains:
//   - what:  what the metric measures (plain language for owner)
//   - why:   why it matters / what good vs bad means
//   - how:   formula or method of calculation
//   - current_state: interpretation of current vs target (BIZ + GRI)
//   - sources: where the data comes from
//
// Source types:
//   - survey:     onboarding survey answer of the current 12-step wizard
//                 (lib/survey/steps.ts); `legacy: true` = a key only the older
//                 form wrote, read as a low-priority fallback
//   - document:   a field of a parsed uploaded file (lib/documents/pipeline.ts);
//                 `field` is a key of lib/documents/synonyms.ts, `doc_type` a
//                 family of document types (lib/documents/doc-types.ts)
//   - formula:    calculated from other metrics (lib/metrics/formulas.ts)
//   - assessment: a section of the company's GRI assessment
//   - prisma:     DB model (prisma/schema.prisma) — no producer today
//   - external:   third-party system (GA, KASE, CRM, ERP, social) — not connected yet
//   - manual:     manual owner input
//   - missing:    «нужен источник: …» — what would have to be provided
//
// Every metric has at least one real path (current survey key, document
// field with a synonym, formula or GRI section) — guarded by
// tests/unit/metrics/metric-invariants.test.ts. Sources are declared in the
// metric's own unit and meaning: an INPUT of a formula (the marketing budget
// for CPL, deal counts for win rate) is never a source of the metric itself.
// ============================================================

// Source types + formatSource moved to the light ./format module so client
// bundles can import them without the 171 KB catalog. Re-exported here for
// back-compat with existing importers. 2026-07-02.
export type { MetricSourceType, MetricSource, MetricPeriod } from "./format";
export { formatSource } from "./format";
import type { MetricPeriod, MetricSource } from "./format";
import { MATURITY_METRIC_DESCRIPTIONS } from "./descriptions-maturity";

export interface MetricDescription {
  label: string;
  what: string;
  why: string;
  how: string;
  /**
   * Sample interpretation text written for a demo company. NEVER show it to a
   * client as their «current state» and never return it from an API.
   */
  current_state?: string;
  sources: MetricSource[];
  /** Explicit unit; when absent the registry infers it from the label. */
  unit?: string;
  /** 'flag' = 1/0 (есть / нет) answer, rendered as «Да / Нет», not as a number. */
  valueKind?: "number" | "flag";
  /** Period of a flow metric (values of other periods are rescaled to it); absent = point value / ratio. */
  period?: MetricPeriod;
  /** Plausible range [min, max] (NPS −100..100, a share 0..100, a score 0..10). */
  range?: readonly [number, number];
}

export interface KpiDescription extends MetricDescription {
  category?: string;
  owner?: string | null;
  method?: string | null;
}

export interface GoalMetricDescription {
  label: string;
  formula: string;
  benchmark: string;
  /** Explicit unit; when absent the registry infers it from label + formula. */
  unit?: string;
  /** Period of a flow metric (values of other periods are rescaled to it); absent = point value / ratio. */
  period?: MetricPeriod;
  /** Plausible range [min, max]. */
  range?: readonly [number, number];
  what: string;
  why: string;
  how: string;
  sources: MetricSource[];
}

export interface GoalFormulaBlock {
  title: string;
  formula: string;
  rules: string[];
  explanation: string;
}

export interface GoalDescriptions {
  number: string;
  title: string;
  formulaBlock?: GoalFormulaBlock;
  items: GoalMetricDescription[];
}

