/**
 * Get BIZ metric description by department and label.
 * Returns undefined if not found.
 */
export function getBizDescription(dept: string, label: string): MetricDescription | undefined {
  return BIZ_METRIC_DESCRIPTIONS[dept]?.[label];
}

/**
 * Get GRI block description by label.
 */
export function getGriDescription(label: string): MetricDescription | undefined {
  return GRI_BLOCK_DESCRIPTIONS[label];
}

/**
 * Get KPI description by exact KPI label.
 * KPI labels include disambiguators for duplicates (e.g. "ROA (KPI)").
 */
export function getKpiDescription(label: string): KpiDescription | undefined {
  // Try direct match, then with " (KPI)" suffix, then with "(KPI)" disambiguator
  return KPI_DESCRIPTIONS[label]
    || KPI_DESCRIPTIONS[`${label} (KPI)`]
    || Object.values(KPI_DESCRIPTIONS).find((k) => k.label === label);
}

/**
 * Get growth-goal description by goal number ("01"–"11").
 */
export function getGoalDescription(number: string): GoalDescriptions | undefined {
  return METRIC_GOAL_DESCRIPTIONS.find((g) => g.number === number);
}

